code:
РепозиторийGit = ЭтаФорма.Объект.РепозиторийGit;
ВеткаГит = ЭтаФорма.Объект.ВеткаGit;
ТокенГит = ЭтаФорма.Объект.ТокенGit;
КаталогЗнаний = ЭтаФорма.Объект.КаталогБазыЗнанийGit;
АдресГитАПИ = ЭтаФорма.Объект.АдресGitAPI;

Результат = "";
ВладелецРепо = "";
ИмяРепо = "";
ПозицияСлэша = СтрНайти(РепозиторийGit, "/");
Если ПозицияСлэша > 0 Тогда
    ВладелецРепо = Лев(РепозиторийGit, ПозицияСлэша - 1);
    ИмяРепо = Сред(РепозиторийGit, ПозицияСлэша + 1);
КонецЕсли;

Заголовки = Новый Соответствие;
Заголовки.Вставить("Authorization", "token " + ТокенГит);

Соединение = Новый HTTPСоединение(АдресГитАПИ, 443, , , , 30, Новый ЗащищенноеСоединениеOpenSSL);

ПутьЗапроса = "/repos/" + ВладелецРепо + "/" + ИмяРепо + "/contents/" + КаталогЗнаний + "?ref=" + ВеткаГит;
HTTPЗапрос = Новый HTTPЗапрос(ПутьЗапроса, Заголовки);
HTTPОтвет = Соединение.Получить(HTTPЗапрос);

Если HTTPОтвет.КодСостояния <> 200 Тогда
    Результат = "Ошибка HTTP: " + HTTPОтвет.КодСостояния + Символы.ПС + HTTPОтвет.ПолучитьТелоКакСтроку();
Иначе
    JSONСтрока = HTTPОтвет.ПолучитьТелоКакСтроку();
    ЧтениеJSON = Новый ЧтениеJSON();
    ЧтениеJSON.УстановитьСтроку(JSONСтрока);
    МассивФайлов = ПрочитатьJSON(ЧтениеJSON, Ложь);
    ЧтениеJSON.Закрыть();

    Результат = "Файлы в каталоге: " + КаталогЗнаний + Символы.ПС;
    Результат = Результат + "========================================" + Символы.ПС;

    Сч = 0;
    Для Каждого Элемент Из МассивФайлов Цикл
        Если НЕ Элемент.Свойство("type") ИЛИ Элемент.type <> "file" Тогда
            Продолжить;
        КонецЕсли;
        Если НЕ Элемент.Свойство("url") Тогда
            Продолжить;
        КонецЕсли;

        Сч = Сч + 1;
        Результат = Результат + Символы.ПС + "Файл " + Сч + ": " + Элемент.name + Символы.ПС;
        Результат = Результат + "----------------------------------------" + Символы.ПС;

        ПутьФайла = "/repos/" + ВладелецРепо + "/" + ИмяРепо + "/contents/" + КаталогЗнаний + "/" + Элемент.name + "?ref=" + ВеткаГит;
        ЗапросФайла = Новый HTTPЗапрос(ПутьФайла, Заголовки);
        ОтветФайла = Соединение.Получить(ЗапросФайла);

        Если ОтветФайла.КодСостояния = 200 Тогда
            JSONФайла = ОтветФайла.ПолучитьТелоКакСтроку();
            ЧитJSON = Новый ЧтениеJSON();
            ЧитJSON.УстановитьСтроку(JSONФайла);
            ДанныеФайла = ПрочитатьJSON(ЧитJSON, Ложь);
            ЧитJSON.Закрыть();

            Если ДанныеФайла.Свойство("content") Тогда
                Двоичка = Base64Значение(ДанныеФайла.content);
                СодФайла = ПолучитьСтрокуИзДвоичныхДанных(Двоичка);

                НомерСтроки = 0;
                Поз = 1;
                Пока Поз <= СтрДлина(СодФайла) И НомерСтроки < 10 Цикл
                    ПозНПС = СтрНайти(СодФайла, Символы.ПС, , Поз);
                    Если ПозНПС = 0 Тогда
                        ПозНПС = СтрДлина(СодФайла) + 1;
                    КонецЕсли;
                    НомерСтроки = НомерСтроки + 1;
                    Результат = Результат + Сред(СодФайла, Поз, ПозНПС - Поз) + Символы.ПС;
                    Поз = ПозНПС + 1;
                КонецЦикла;
            Иначе
                Результат = Результат + "[Нет содержимого]" + Символы.ПС;
            КонецЕсли;
        Иначе
            Результат = Результат + "[Ошибка загрузки: " + ОтветФайла.КодСостояния + "]" + Символы.ПС;
        КонецЕсли;
    КонецЦикла;

    Если Сч = 0 Тогда
        Результат = Результат + "Файлы не найдены" + Символы.ПС;
    КонецЕсли;
КонецЕсли;
